/*
 * Everything the plan page draws, worked out once. Times are shown in the coach's zone
 * (Europe/Paris), the zone saveStep reads them back in. Words come from Strings with
 * {tags} (CONVENTIONS, Words); kinds and statuses from their option sets.
 * A homework row also carries its hand-ins as they came (Work/Versions shapes them, DBU-06).
 * A check-in row (DBU-10) carries the steps it may follow (anchors: this plan's live sessions and
 * homework) and, once answered, its answer with the answer's own copy of its questions.
 */
if (Inputs.steps === undefined || Inputs.kinds === undefined || Inputs.statuses === undefined || Inputs.t === undefined) return;
const t = Inputs.t;
const fill = (s, v) => Object.keys(v).reduce((out, k) => out.split('{' + k + '}').join(String(v[k])), String(s || ''));
const get = (m, k) => (m && typeof m.get === 'function' ? m.get(k) : m && m[k]);
const kinds = (Inputs.kinds || []).map((k) => ({ value: get(k, 'value'), labelKey: get(k, 'labelKey'), bg: get(k, 'bg'), fg: get(k, 'fg') }));
const statuses = (Inputs.statuses || []).map((s) => ({ value: get(s, 'value'), kind: get(s, 'kind'), labelKey: get(s, 'labelKey'), bg: get(s, 'bg'), fg: get(s, 'fg') }));
const TZ = 'Europe/Paris';
const day = (iso) => new Date(iso).toLocaleDateString('en-GB', { timeZone: TZ, weekday: 'short', day: 'numeric', month: 'short' });
const time = (iso) => new Date(iso).toLocaleTimeString('en-GB', { timeZone: TZ, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });

const learner = Inputs.learner || {};
const plan = Inputs.plan || null;
const steps = Array.isArray(Inputs.steps) ? Inputs.steps : [];
const subs = Array.isArray(Inputs.submissions) ? Inputs.submissions : [];
const answers = Array.isArray(Inputs.checkins) ? Inputs.checkins : [];
const name = learner.name || learner.email || '';
const first = name.split(' ')[0];
const anchors = steps.filter((s) => s.kind === 'live' || s.kind === 'homework').map((s) => ({ id: s.id, label: s.title || '' }));

const rowOf = (s) => {
  const kind = kinds.find((k) => k.value === s.kind) || {};
  const status = statuses.find((x) => x.kind === s.kind && x.value === s.status) || {};
  const minutes = Number.isInteger(s.durationMin) ? s.durationMin : 60;
  const handIns = s.kind === 'homework' ? subs.filter((x) => x.step === s.id) : [];
  const answer = s.kind === 'checkin' ? answers.find((a) => a.step === s.id) || null : null;
  let detail = [];
  if (s.kind === 'live') {
    detail.push(s.startsAt ? day(s.startsAt) + ', ' + time(s.startsAt) : t.toBook);
    detail.push(fill(t.minutes, { min: minutes }));
    if (s.attended === true) detail.push(t.attended);
  } else if (s.kind === 'homework') {
    detail.push(s.dueAt ? fill(t.due, { date: day(s.dueAt) }) : t.noDue);
    if (s.fromLibraryItem) detail.push(t.fromLibrary);
    if (!String(s.brief || '').trim()) detail.push(t.noBrief);
    if (handIns.length) detail.push(fill(t.versions, { n: handIns.length }));
  } else {
    const anchor = s.sendAfter && s.sendAfter.step ? steps.find((x) => x.id === s.sendAfter.step) : null;
    if (anchor) {
      const days = Number(s.sendAfter.days) || 0;
      detail.push(fill(days === 0 ? t.afterSame : t.after, { days, title: anchor.title || '' }));
    }
    if (s.sendsAt) detail.push(fill(t.sends, { date: day(s.sendsAt) }));
    else if (!anchor) detail.push(t.noSend);
    if (answer && answer.answeredAt) detail.push(fill(t.answered, { date: day(answer.answeredAt) }));
  }
  const shared = s.shared === true;
  return {
    id: s.id,
    kindKey: kind.labelKey || '',
    kindBg: kind.bg || 'var(--muted)',
    kindFg: kind.fg || 'var(--muted-foreground)',
    statusKey: status.labelKey || '',
    statusBg: status.bg || 'var(--muted)',
    statusFg: status.fg || 'var(--muted-foreground)',
    shared,
    draft: !shared,
    sharedKey: shared ? 'plan.shared' : 'plan.draft',
    title: s.title || '',
    detail: detail.join(' · '),
    rowBg: shared ? 'var(--surface)' : 'var(--background)',
    rowBorder: shared ? 'solid' : 'dashed',
    isLive: s.kind === 'live',
    isHomework: s.kind === 'homework',
    isCheckin: s.kind === 'checkin',
    step: s,
    handIns,
    hasHandIns: handIns.length > 0,
    anchors: s.kind === 'checkin' ? anchors : [],
    hasAnswers: !!answer,
    answerQuestions: answer && answer.form && Array.isArray(answer.form.questions) ? answer.form.questions : [],
    answerValues: answer && answer.answers ? answer.answers : {},
    hasTime: s.kind === 'live' && !!s.startsAt,
    startsAt: s.startsAt || '',
    durationMin: minutes,
    meetingLink: s.meetingLink || (plan && plan.meetingLink) || '',
    calDetails: plan ? plan.title : '',
    attendeeName: name,
    attendeeEmail: learner.email || ''
  };
};
const rows = steps.map(rowOf);
const live = steps.filter((s) => s.kind === 'live');
const liveMinutes = live.reduce((m, s) => m + (Number.isInteger(s.durationMin) ? s.durationMin : 60), 0);
const h = Math.floor(liveMinutes / 60);
const m = liveMinutes % 60;

Outputs.name = name;
Outputs.first = first;
Outputs.detail = [learner.jobTitle, learner.organisation, learner.email].filter(Boolean).join(' · ');
Outputs.planId = plan ? plan.id : '';
Outputs.hasPlan = !!plan;
Outputs.noPlan = !plan;
Outputs.statusKey = plan ? 'plan.plan' + plan.status.charAt(0).toUpperCase() + plan.status.slice(1) : '';
Outputs.live = String(live.length);
Outputs.homework = String(steps.filter((s) => s.kind === 'homework').length);
Outputs.hours = m ? fill(t.hoursMinutes, { h, m }) : fill(t.hours, { h });
Outputs.empty = steps.length === 0;
Outputs.startedFrom = (plan && plan.templateTitle) || t.blank;
Outputs.suggestedTitle = plan ? plan.title : '';
const shown = Inputs.learnerView === true ? rows.filter((r) => r.shared) : rows;
Outputs.rows = shown;
Outputs.nothingShared = Inputs.learnerView === true && shown.length === 0;
Outputs.done();

// One object, so the shaping waits for every word at once (each Translation arrives on its own).
const keys = ['toBook', 'minutes', 'attended', 'due', 'noDue', 'fromLibrary', 'noBrief', 'versions', 'sends', 'noSend', 'hours', 'hoursMinutes', 'blank', 'after', 'afterSame', 'answered'];
if (keys.some((k) => Inputs[k] === undefined)) return;
Outputs.t = keys.reduce((o, k) => Object.assign(o, { [k]: Inputs[k] }), {});
